create table d_trd_daily_accrual_fee(contract_code string comment '合约编号',calc_date string comment '计提日期',fee_type string comment '费用类型',fee_rate string comment '费率',accrual_amount string comment '当日计提费用金额',accumulated_accrual_amount string comment '累计计提费用金额',daily_take_amount string comment '当日提取费用',accumulated_take_amount string comment '累计已提取计提费用',accumulated_untake_amount string comment '累计未提取计提费用',created_datetime string comment '创建时间',updated_datetime string comment '修改时间',updated_by string comment '修改人',created_by string comment '创建人',notional string comment '动态名义本金',key_instrument_id string comment '场外合约主数据代码',unsettle_amount string comment '累计应结未结费用',data_time string comment '【AI】数据时间') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
